        "code": {
          "text": "Bilateral foot pins and needles and numbness"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Progressive over 3–4 months; now extends to mid-shin bilaterally, right equal to left."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-2",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-2",
        "status": "final",
        "code": {
          "text": "Burning pain in soles"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Burning sensation described as like being on fire; worse at night and wakes the patient."
      }
    },
