      "fullUrl": "https://example.org/fhir/Observation/observation-3",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-3",
        "status": "final",
        "code": {
          "text": "Calf and leg symptoms"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Dull ache in calves; legs feel heavy and tired."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-4",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-4",
        "status": "final",
        "code": {
          "text": "Low back pain and reported prior MRI"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Long-standing intermittent low back pain. Patient and daughter report a previous regional hospital MRI showed an L4/5 disc protrusion with nerve root involvement."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-5",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-5",
        "status": "final",
        "code": {
          "text": "Reported absence of weakness, injury, and falls"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "No clear weakness, no recent back injury, and no falls reported."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-6",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-6",
        "status": "final",
        "code": {
          "text": "Reported absence of red-flag symptoms"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Denies saddle anaesthesia, bowel or bladder incontinence, and urinary retention."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-7",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-7",
        "status": "final",
        "code": {
          "text": "Relevant reported medical history"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "No known diabetes, B12 issues, or thyroid issues. Rare alcohol use."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-8",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-8",
        "status": "final",
        "code": {
          "text": "Temperature assessment"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Afebrile."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-9",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-9",
        "status": "final",
        "code": {
          "text": "Lower limb power"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Power 5/5 throughout both lower limbs; able to heel- and toe-walk."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-10",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-10",
        "status": "final",
        "code": {
          "text": "Lower limb reflexes"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Patellar reflexes decreased; Achilles reflexes trace bilaterally."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-11",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-11",
        "status": "final",
        "code": {
          "text": "Lower limb light touch and pinprick sensation"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Reduced in a symmetrical stocking pattern to mid-shin bilaterally."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-12",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-12",
        "status": "final",
        "code": {
          "text": "Vibration sensation"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Reduced at great toes, better at ankles."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-13",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-13",
        "status": "final",
        "code": {
          "text": "Gait"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Normal."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-14",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-14",
        "status": "final",
        "code": {
          "text": "Foot skin and peripheral pulses"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "No foot ulcers; pulses palpable."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-15",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-15",
        "status": "final",
        "code": {
          "text": "Back red-flag examination"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "No red-flag back signs today."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/MedicationRequest/medication-request-1",
      "resource": {
        "resourceType": "MedicationRequest",
        "id": "medication-request-1",
        "status": "active",
        "intent": "order",
        "medicationCodeableConcept": {
          "text": "Amitriptyline"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "dosageInstruction": [
          {
            "text": "Take 10 mg at night for 7 nights, then increase to 20 mg at night if pain persists and the medicine is tolerated."
          }
        ],
        "note": [
          {
            "text": "Warned about drowsiness and dry mouth, and that the patient might feel unwell and sleepy in the morning. Advised not to drive or operate a forklift if groggy."
          }
        ]
      }
    }
  ]
}
